import type { Option } from "effect";
import type { Command } from "foldkit";
import { Ui } from "foldkit";

export const { Model } = Ui.Slider;
export type Model = Ui.Slider.Model;

export const { Message, OutMessage } = Ui.Slider;
export type Message = Ui.Slider.Message;
export type OutMessage = Ui.Slider.OutMessage;
export type CancelledDrag = Ui.Slider.CancelledDrag;
export type MovedDragPointer = Ui.Slider.MovedDragPointer;
export type PressedKeyboardNavigation = Ui.Slider.PressedKeyboardNavigation;
export type PressedPointer = Ui.Slider.PressedPointer;
export type PressedThumb = Ui.Slider.PressedThumb;
export type ReleasedDragPointer = Ui.Slider.ReleasedDragPointer;

export type InitConfig = Ui.Slider.InitConfig;
export type SliderAttributes = Ui.Slider.SliderAttributes;
export type ViewInputs = Ui.Slider.ViewInputs;
export type InitReturn = readonly [Model, readonly Command.Command<Message>[]];
export type UpdateReturn = readonly [
  Model,
  readonly Command.Command<Message>[],
  Option.Option<OutMessage>,
];

export const init = (config: InitConfig): InitReturn => [
  Ui.Slider.init(config),
  [],
];

export const {
  fractionOfValue,
  reflectRange,
  reflectValue,
  subscriptions,
  subscriptionsForRoot,
  update,
  view,
} = Ui.Slider;

export {
  filledTrackClassName,
  headerClassName,
  labelClassName,
  rootClassName,
  sliderFieldView,
  thumbClassName,
  trackClassName,
  valueClassName,
} from "./view";
export type { SliderFieldViewInput } from "./view";

import type { Ui } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

export const fieldClassName = "flex w-full min-w-64 max-w-sm flex-col gap-2";

export const headerClassName =
  "flex items-center justify-between text-sm text-gray-900";

export const labelClassName = "cursor-pointer select-none font-medium";

export const valueClassName = "tabular-nums text-gray-600";

export const rootClassName =
  "relative flex h-6 w-full touch-none select-none items-center";

export const trackClassName = "h-1.5 w-full rounded-full bg-gray-200";

export const filledTrackClassName = "h-full rounded-full bg-accent-600";

export const thumbClassName =
  "h-5 w-5 cursor-grab rounded-full border-2 border-accent-600 bg-white shadow focus:outline-none focus-visible:ring-2 focus-visible:ring-accent-600 focus-visible:ring-offset-2 data-[disabled]:cursor-not-allowed data-[disabled]:opacity-60 data-[dragging]:cursor-grabbing";

export type SliderFieldViewInput = Readonly<{
  attributes: Ui.Slider.SliderAttributes;
  label: string;
  valueText: string;
}>;

export const sliderFieldView = ({
  attributes,
  label,
  valueText,
}: SliderFieldViewInput): Html => {
  const h = html<Ui.Slider.Message>();

  return h.div(
    [h.Class(fieldClassName)],
    [
      h.div(
        [h.Class(headerClassName)],
        [
          h.label([...attributes.label, h.Class(labelClassName)], [label]),
          h.span([h.Class(valueClassName)], [valueText]),
        ]
      ),
      h.div(
        [...attributes.root, h.Class(rootClassName)],
        [
          h.div(
            [...attributes.track, h.Class(trackClassName)],
            [
              h.div(
                [...attributes.filledTrack, h.Class(filledTrackClassName)],
                []
              ),
            ]
          ),
          h.div([...attributes.thumb, h.Class(thumbClassName)], []),
          h.input(attributes.hiddenInput),
        ]
      ),
    ]
  );
};

import { Match as M, Option, Schema as S } from "effect";
import { Command, Scene, Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";
import { describe, test } from "vitest";

import * as Slider from "./index";

const GotSliderMessage = m("GotSliderMessage", {
  message: Slider.Message,
});

const Model = S.Struct({
  slider: Slider.Model,
  status: S.String,
});

type Model = typeof Model.Type;

const Message = S.Union([GotSliderMessage]);
type Message = typeof Message.Type;

const initialModel: Model = {
  slider: Slider.init({
    id: "registry-slider",
    min: 0,
    max: 10,
    step: 1,
    initialValue: 4,
  })[0],
  status: "Rating: 4 of 10",
};

const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      GotSliderMessage: ({ message }) => {
        const [slider, commands, maybeOutMessage] = Slider.update(
          model.slider,
          message
        );
        const status = Option.match(maybeOutMessage, {
          onNone: () => model.status,
          onSome: M.type<Slider.OutMessage>().pipe(
            M.tagsExhaustive({
              ChangedValue: ({ value }) => `Rating: ${value} of 10`,
            })
          ),
        });

        return [
          evo(model, {
            slider: () => slider,
            status: () => status,
          }),
          Command.mapMessages(commands, (message) =>
            GotSliderMessage({ message })
          ),
        ];
      },
    })
  );

const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return h.div(
    [h.Class("space-y-3")],
    [
      h.submodel({
        slotId: model.slider.id,
        model: model.slider,
        view: Slider.view,
        viewInputs: {
          formatValue: (value) => `${value} of 10`,
          toView: (attributes) =>
            Slider.sliderFieldView({
              attributes,
              label: "Rating",
              valueText: `${model.slider.value} of 10`,
            }),
        },
        toParentMessage: (message) => GotSliderMessage({ message }),
      }),
      h.p([], [model.status]),
    ]
  );
});

describe("Slider registry view", () => {
  test("renders accessible value and applies keyboard value changes", () => {
    Scene.scene(
      { update, view },
      Scene.with(initialModel),
      Scene.expect(Scene.role("slider", { name: "Rating" })).toHaveAttr(
        "aria-valuenow",
        "4"
      ),
      Scene.expect(Scene.text("Rating: 4 of 10")).toExist(),
      Scene.keydown(Scene.role("slider", { name: "Rating" }), "ArrowRight"),
      Scene.expect(Scene.role("slider", { name: "Rating" })).toHaveAttr(
        "aria-valuenow",
        "5"
      ),
      Scene.expect(Scene.text("Rating: 5 of 10")).toExist()
    );
  });
});
